const key = 'score';
const id = 42;

function makeRecord(name, score) {
  return {
    id,
    name,
    [`${key}_normalized`]: score / 100,
    greet() {
      return `${name}: ${score}`;
    },
  };
}

const record = makeRecord('Ada', 87);
console.log(record.id, record.name, record.score_normalized);
console.log(record.greet());

const merged = { ...record, score_normalized: 1 };
console.log(merged.score_normalized, merged.id);
